import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Radio, Download, Camera, Sparkles, Users, Bell, BellOff,
  Upload, Loader2, Play, Pause, X, Image, Heart, Share2
} from 'lucide-react';
import { useApp } from '../../context/AppContext';
import { orchestratorApi } from '../../utils/api';

// 附近粉丝卡片
const NearbyFansCard = ({ fansData, onRegister }) => (
  <div className="glass rounded-xl p-4 border border-neon-pink/30 bg-neon-pink/5">
    <div className="flex items-center justify-between mb-2">
      <div className="flex items-center">
        <Users className="w-5 h-5 mr-2 text-neon-pink" />
        <h4 className="font-bold text-white">附近粉丝</h4>
      </div>
      <button onClick={onRegister} className="text-xs text-neon-pink hover:underline">
        加入我们
      </button>
    </div>
    <p className="text-sm text-pink-300">{fansData?.message || '正在加载...'}</p>
  </div>
);

// 纪念卡片展示
const SouvenirCard = ({ data, onDownload }) => (
  <motion.div
    initial={{ opacity: 0, scale: 0.95 }}
    animate={{ opacity: 1, scale: 1 }}
    className="glass rounded-xl p-4 border border-neon-purple/30"
  >
    {data.cardImageUrl && (
      <img src={data.cardImageUrl} alt="纪念卡片" className="w-full rounded-lg mb-3" />
    )}
    <p className="text-sm text-purple-300 mb-3">{data.message}</p>
    <div className="flex items-center justify-between">
      <span className="text-xs text-gray-400">{data.singer} · {data.city}</span>
      {data.cardImageUrl && (
        <button
          onClick={onDownload}
          className="flex items-center space-x-1 text-xs text-neon-purple hover:underline"
        >
          <Download className="w-3.5 h-3.5" />
          <span>下载</span>
        </button>
      )}
    </div>
    {data.tips && (
      <p className="text-xs text-yellow-400 mt-2">💡 {data.tips}</p>
    )}
  </motion.div>
);

// 专属电台卡片
const RadioCard = ({ data, currentSong, onTogglePlay }) => (
  <motion.div
    initial={{ opacity: 0, scale: 0.95 }}
    animate={{ opacity: 1, scale: 1 }}
    className="glass rounded-xl p-4 border border-orange-500/30 bg-orange-500/5"
  >
    <div className="flex items-center space-x-3 mb-3">
      <div className="w-12 h-12 rounded-full bg-gradient-to-r from-orange-500 to-red-500 flex items-center justify-center flex-shrink-0">
        <Radio className="w-6 h-6 text-white" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="font-bold text-white truncate">{data.radioName}</p>
        <p className="text-xs text-orange-300 truncate">{data.tagline}</p>
      </div>
    </div>
    <p className="text-sm text-gray-400 mb-3">{data.broadcast}</p>
    {data.playlist?.length > 0 && (
      <div className="space-y-1.5">
        {data.playlist.slice(0, 5).map((song, i) => (
          <div key={i} className="flex items-center space-x-2 text-xs px-2 py-1 rounded bg-white/5 hover:bg-white/10 transition-colors">
            <button onClick={() => onTogglePlay(song)} className="flex-shrink-0">
              {currentSong?.name === song.name && currentSong?.isPlaying
                ? <Pause className="w-3.5 h-3.5 text-orange-400" />
                : <Play className="w-3.5 h-3.5 text-gray-400" />
              }
            </button>
            <span className="text-white truncate flex-1">{song.name}</span>
            <span className="text-gray-500 flex-shrink-0">{song.artist}</span>
          </div>
        ))}
      </div>
    )}
  </motion.div>
);

// 照片生成卡片
const PhotoCard = ({ data, type, onDownload }) => (
  <motion.div
    initial={{ opacity: 0, scale: 0.95 }}
    animate={{ opacity: 1, scale: 1 }}
    className="glass rounded-xl p-4 border border-neon-blue/30"
  >
    {data.generatedPhotoUrl || data.resultImageUrl || data.imageUrl ? (
      <img
        src={data.generatedPhotoUrl || data.resultImageUrl || data.imageUrl}
        alt={type}
        className="w-full rounded-lg mb-3"
      />
    ) : (
      <div className="w-full h-48 bg-white/5 rounded-lg flex items-center justify-center mb-3">
        <Image className="w-12 h-12 text-gray-600" />
      </div>
    )}
    <p className="text-sm text-blue-300 mb-2">{data.message || data.description || data.quote}</p>
    <div className="flex space-x-2">
      {(data.canDownload !== false) && (
        <button
          onClick={onDownload}
          className="flex-1 flex items-center justify-center space-x-1.5 py-2 bg-neon-blue/20 border border-neon-blue/50 rounded-lg text-neon-blue text-xs hover:bg-neon-blue/30"
        >
          <Download className="w-3.5 h-3.5" />
          <span>下载</span>
        </button>
      )}
    </div>
  </motion.div>
);

const OrchSouvenirPanel = ({ onSelectSinger }) => {
  const { orchSession, orchUserId } = useApp();
  const fileInputRef = useRef(null);
  const audioRef = useRef(null);

  const [fans, setFans] = useState(null);
  const [fansLoading, setFansLoading] = useState(false);
  const [radioData, setRadioData] = useState(null);
  const [radioLoading, setRadioLoading] = useState(false);
  const [souvenirData, setSouvenirData] = useState(null);
  const [souvenirLoading, setSouvenirLoading] = useState(false);
  const [photoData, setPhotoData] = useState(null);
  const [photoLoading, setPhotoLoading] = useState(false);
  const [photoType, setPhotoType] = useState(null);
  const [reminderEnabled, setReminderEnabled] = useState(false);
  const [reminderLoading, setReminderLoading] = useState(false);
  const [currentSong, setCurrentSong] = useState(null);
  const [tab, setTab] = useState('radio');

  // 加载附近粉丝
  const loadFans = async () => {
    if (!orchSession) return;
    setFansLoading(true);
    try {
      const res = await orchestratorApi.getNearbyFans(orchSession);
      if (res.success) setFans(res.data);
    } catch { setFans(null); }
    setFansLoading(false);
  };

  // 注册为粉丝
  const handleRegisterFan = async () => {
    if (!orchSession) return;
    try {
      await orchestratorApi.registerFan(orchSession, Number(orchUserId));
      loadFans();
    } catch {}
  };

  // 切换提醒
  const handleToggleReminder = async () => {
    if (!orchSession) return;
    setReminderLoading(true);
    try {
      const next = !reminderEnabled;
      await orchestratorApi.toggleReminder(orchSession, next);
      setReminderEnabled(next);
    } catch {}
    setReminderLoading(false);
  };

  // 生成专属电台
  const handleCreateRadio = async (mood = 'happy') => {
    if (!orchSession) return;
    setRadioLoading(true);
    try {
      const res = await orchestratorApi.createRadio(orchSession, mood);
      if (res.success) setRadioData(res.data);
    } catch {}
    setRadioLoading(false);
  };

  // 生成纪念卡片
  const handleSouvenir = async () => {
    if (!orchSession) return;
    setSouvenirLoading(true);
    try {
      const res = await orchestratorApi.generateSouvenir(orchSession, '今晚太开心了！');
      if (res.success) setSouvenirData(res.data);
    } catch {}
    setSouvenirLoading(false);
  };

  // 上传照片（支持合照/妆造/拍立得）
  const handlePhotoUpload = async (type) => {
    fileInputRef.current?.click();
    fileInputRef.current && (fileInputRef.current.dataset.type = type);
  };

  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file || !orchSession) return;
    const type = fileInputRef.current?.dataset?.type || 'photo';
    setPhotoLoading(true);
    setPhotoType(type);
    try {
      let res;
      if (type === 'makeup') {
        res = await orchestratorApi.uploadVirtualMakeup(orchSession, file);
      } else if (type === 'polaroid') {
        res = await orchestratorApi.uploadPolaroid(orchSession, file, '演唱会超开心！');
      } else {
        res = await orchestratorApi.uploadVirtualPhoto(orchSession, file);
      }
      if (res.data?.success) setPhotoData(res.data.data);
    } catch {}
    setPhotoLoading(false);
    e.target.value = '';
  };

  const downloadImage = async (url, name) => {
    try {
      const res = await fetch(url);
      const blob = await res.blob();
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `${name}.jpg`;
      link.click();
    } catch { /* 静默 */ }
  };

  const togglePlaySong = (song) => {
    if (!audioRef.current) {
      audioRef.current = new Audio();
    }
    const audio = audioRef.current;
    if (currentSong?.name === song.name && currentSong?.isPlaying) {
      audio.pause();
      setCurrentSong({ ...song, isPlaying: false });
    } else {
      audio.src = song.url;
      audio.play();
      setCurrentSong({ ...song, isPlaying: true });
      audio.onended = () => setCurrentSong(prev => prev ? { ...prev, isPlaying: false } : null);
    }
  };

  const panelTabs = [
    { id: 'radio', label: '专属电台', icon: Radio },
    { id: 'souvenir', label: '纪念卡片', icon: Sparkles },
    { id: 'photo', label: '应援拍照', icon: Camera },
  ];

  return (
    <div className="glass rounded-2xl border border-white/10 p-6">
      {/* 隐藏的文件输入 */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={handleFileChange}
      />

      {/* 面板标题 */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-xl font-bold text-white">纪念互动</h2>
          <p className="text-sm text-gray-400">生成专属纪念品，记录与偶像的每一刻</p>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={loadFans}
            className="flex items-center space-x-1.5 px-3 py-1.5 glass rounded-lg border border-neon-pink/30 hover:border-neon-pink/50 text-xs text-neon-pink transition-colors"
          >
            <Users className="w-3.5 h-3.5" />
            <span>找粉丝</span>
          </button>
          <button
            onClick={handleToggleReminder}
            disabled={reminderLoading}
            className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg text-xs transition-colors ${
              reminderEnabled
                ? 'bg-neon-blue/20 border border-neon-blue/50 text-neon-blue'
                : 'glass border border-white/10 text-gray-400 hover:text-white'
            }`}
          >
            {reminderEnabled ? <Bell className="w-3.5 h-3.5" /> : <BellOff className="w-3.5 h-3.5" />}
            <span>{reminderEnabled ? '提醒已开' : '开启提醒'}</span>
          </button>
        </div>
      </div>

      {/* 附近粉丝 */}
      {fans && (
        <div className="mb-4">
          <NearbyFansCard fansData={fans} onRegister={handleRegisterFan} />
        </div>
      )}

      {/* 子 Tab */}
      <div className="flex space-x-2 mb-4">
        {panelTabs.map(t => {
          const Icon = t.icon;
          const isActive = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg text-xs transition-all ${
                isActive
                  ? 'bg-neon-blue/20 border border-neon-blue/50 text-neon-blue'
                  : 'glass border border-white/10 text-gray-400 hover:text-white'
              }`}
            >
              <Icon className="w-3.5 h-3.5" />
              <span>{t.label}</span>
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* 左侧：操作区 */}
        <div className="space-y-3">

          {/* 专属电台 */}
          {tab === 'radio' && (
            <>
              <button
                onClick={() => handleCreateRadio('happy')}
                disabled={radioLoading}
                className="w-full flex items-center justify-center space-x-2 py-3 bg-gradient-to-r from-orange-500 to-red-500 rounded-xl text-white font-medium disabled:opacity-50"
              >
                {radioLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Radio className="w-4 h-4" />}
                <span>🎧 生成专属电台</span>
              </button>
              <div className="grid grid-cols-2 gap-2">
                {['happy', 'nostalgic', 'excited', 'sad'].map(mood => (
                  <button
                    key={mood}
                    onClick={() => handleCreateRadio(mood)}
                    disabled={radioLoading}
                    className="py-2 px-3 glass rounded-lg border border-white/10 text-xs text-gray-400 hover:border-orange-500/50 hover:text-orange-300 transition-colors disabled:opacity-50"
                  >
                    {mood === 'happy' ? '😊 开心' : mood === 'sad' ? '😢 伤感' : mood === 'nostalgic' ? '🎶 怀旧' : '🔥 兴奋'}
                  </button>
                ))}
              </div>
            </>
          )}

          {/* 纪念卡片 */}
          {tab === 'souvenir' && (
            <>
              <button
                onClick={handleSouvenir}
                disabled={souvenirLoading}
                className="w-full flex items-center justify-center space-x-2 py-3 bg-gradient-to-r from-neon-purple to-neon-pink rounded-xl text-white font-medium disabled:opacity-50"
              >
                {souvenirLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                <span>✨ 生成纪念卡片</span>
              </button>
              {souvenirData && (
                <button
                  onClick={() => souvenirData.cardImageUrl && downloadImage(souvenirData.cardImageUrl, 'concert-souvenir')}
                  disabled={!souvenirData.cardImageUrl}
                  className="w-full flex items-center justify-center space-x-2 py-2.5 glass rounded-xl border border-neon-purple/30 text-neon-purple text-sm disabled:opacity-40"
                >
                  <Download className="w-4 h-4" />
                  <span>下载纪念卡片</span>
                </button>
              )}
            </>
          )}

          {/* 应援拍照 */}
          {tab === 'photo' && (
            <>
              <button
                onClick={() => handlePhotoUpload('photo')}
                disabled={photoLoading}
                className="w-full flex items-center justify-center space-x-2 py-3 bg-gradient-to-r from-neon-blue to-neon-purple rounded-xl text-white font-medium disabled:opacity-50"
              >
                {photoLoading && photoType === 'photo' ? <Loader2 className="w-4 h-4 animate-spin" /> : <Camera className="w-4 h-4" />}
                <span>📸 上传合照</span>
              </button>
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => handlePhotoUpload('makeup')}
                  disabled={photoLoading}
                  className="py-2.5 px-3 glass rounded-xl border border-white/10 text-xs text-gray-400 hover:border-pink-500/50 hover:text-pink-300 transition-colors disabled:opacity-50"
                >
                  💄 应援妆造
                </button>
                <button
                  onClick={() => handlePhotoUpload('polaroid')}
                  disabled={photoLoading}
                  className="py-2.5 px-3 glass rounded-xl border border-white/10 text-xs text-gray-400 hover:border-yellow-500/50 hover:text-yellow-300 transition-colors disabled:opacity-50"
                >
                  📷 演唱会拍立得
                </button>
              </div>
            </>
          )}
        </div>

        {/* 右侧：结果展示 */}
        <div className="space-y-3">
          {tab === 'radio' && radioData && (
            <RadioCard data={radioData} currentSong={currentSong} onTogglePlay={togglePlaySong} />
          )}
          {tab === 'souvenir' && souvenirData && (
            <SouvenirCard
              data={souvenirData}
              onDownload={() => souvenirData.cardImageUrl && downloadImage(souvenirData.cardImageUrl, 'concert-card')}
            />
          )}
          {tab === 'photo' && photoData && (
            <PhotoCard
              data={photoData}
              type={photoType}
              onDownload={() => {
                const url = photoData.generatedPhotoUrl || photoData.resultImageUrl || photoData.imageUrl;
                url && downloadImage(url, `concert-${photoType}`);
              }}
            />
          )}

          {/* 空状态 */}
          {!radioData && tab === 'radio' && (
            <div className="glass rounded-xl p-6 border border-white/10 text-center text-gray-500 text-sm h-full flex flex-col items-center justify-center">
              <Radio className="w-10 h-10 mb-3 opacity-30" />
              <p>点击左侧按钮生成专属电台</p>
            </div>
          )}
          {!souvenirData && tab === 'souvenir' && (
            <div className="glass rounded-xl p-6 border border-white/10 text-center text-gray-500 text-sm h-full flex flex-col items-center justify-center">
              <Sparkles className="w-10 h-10 mb-3 opacity-30" />
              <p>生成你的演唱会纪念卡片</p>
            </div>
          )}
          {!photoData && tab === 'photo' && (
            <div className="glass rounded-xl p-6 border border-white/10 text-center text-gray-500 text-sm h-full flex flex-col items-center justify-center">
              <Camera className="w-10 h-10 mb-3 opacity-30" />
              <p>上传照片生成应援效果</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default OrchSouvenirPanel;
