import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Sparkles, MessageCircle, Radio, Map, Bot, Send, ChevronRight,
  Loader2, Check, Zap
} from 'lucide-react';
import { useApp } from '../context/AppContext';
import { orchestratorApi } from '../utils/api';
import PlanningTab from '../components/agent/PlanningTab';
import CelebrityChatTab from '../components/agent/CelebrityChatTab';
import MusicRadioTab from '../components/agent/MusicRadioTab';
import OrchSouvenirPanel from '../components/agent/OrchSouvenirPanel';

const TABS = [
  { id: 'planning', label: '智能规划', icon: Map, color: 'from-blue-500 to-cyan-500', desc: 'AI定制你的演唱会行程' },
  { id: 'celebrity', label: '歌手对话', icon: MessageCircle, color: 'from-purple-500 to-pink-500', desc: '与偶像AI实时聊天' },
  { id: 'music', label: '情绪电台', icon: Radio, color: 'from-orange-500 to-red-500', desc: '根据心情推荐歌单' },
  { id: 'souvenir', label: '纪念互动', icon: Sparkles, color: 'from-neon-blue to-neon-purple', desc: '生成专属纪念卡片和应援照' },
];

const THINK_STEPS = [
  '🔍 解析你的需求...',
  '🤖 调度 AI Agent...',
  '🎵 整合信息资源...',
  '✨ 生成回复内容...',
];

const AgentPage = ({ onSelectSinger }) => {
  const { orchSession, orchUserId } = useApp();
  const [activeTab, setActiveTab] = useState('planning');
  const [chatInput, setChatInput] = useState('');
  const [orchMessages, setOrchMessages] = useState([]);
  const [orchLoading, setOrchLoading] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [sessionInfo, setSessionInfo] = useState(null);
  const chatEndRef = useRef(null);
  const stepTimerRef = useRef(null);

  // 加载会话上下文
  useEffect(() => {
    if (!orchSession) return;
    orchestratorApi.getSession(orchSession).then(res => {
      if (res.success) setSessionInfo(res.data);
    }).catch(console.error);
  }, [orchSession, orchMessages.length]);

  // 自动滚动
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [orchMessages]);

  const handleOrchChat = async () => {
    if (!chatInput.trim() || orchLoading) return;
    const input = chatInput.trim();
    setChatInput('');
    setOrchMessages(prev => [...prev, { role: 'user', content: input }]);
    setOrchLoading(true);

    // 思考步骤动画
    setCurrentStep(0);
    stepTimerRef.current = setInterval(() => {
      setCurrentStep(prev => prev < THINK_STEPS.length - 1 ? prev + 1 : prev);
    }, 600);

    try {
      const res = await orchestratorApi.chat(orchSession, Number(orchUserId), input);
      if (res.success) {
        setOrchMessages(prev => [...prev, { role: 'assistant', content: res.data }]);
        // 刷新上下文
        const info = await orchestratorApi.getSession(orchSession);
        if (info.success) setSessionInfo(info.data);
      }
    } catch (err) {
      setOrchMessages(prev => [...prev, { role: 'assistant', content: '抱歉，服务暂时不可用，请稍后重试。' }]);
    } finally {
      clearInterval(stepTimerRef.current);
      setOrchLoading(false);
      setCurrentStep(-1);
    }
  };

  const ActiveTabComponent = {
    planning: PlanningTab,
    celebrity: CelebrityChatTab,
    music: MusicRadioTab,
    souvenir: OrchSouvenirPanel,
  }[activeTab] || PlanningTab;

  return (
    <div className="min-h-screen pt-20 pb-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* 页面标题 */}
        <div className="text-center mb-6">
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            className="inline-flex items-center space-x-2 px-4 py-2 glass rounded-full border border-neon-blue/30 mb-4"
          >
            <Bot className="w-5 h-5 text-neon-blue" />
            <span className="text-sm text-gray-300">演唱会专属 AI 管家</span>
            {orchSession && (
              <span className="text-xs text-neon-green ml-2">● 在线</span>
            )}
          </motion.div>
          <h1 className="text-3xl md:text-4xl font-bold text-white mb-1">
            一站式演唱会智能助手
          </h1>
          <p className="text-gray-400">告诉我想看谁、什么时候出发，AI 全程搞定</p>
        </div>

        {/* 统一管家对话区（始终可见） */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="glass rounded-2xl border border-white/10 mb-6 overflow-hidden"
        >
          {/* 对话区域 */}
          <div className="h-48 overflow-y-auto p-4 space-y-3">
            {orchMessages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full text-gray-500 text-sm">
                <Bot className="w-10 h-10 mb-3 opacity-30" />
                <p>试试说："我想看周杰伦演唱会，帮我规划行程"</p>
                <p className="text-xs mt-1 opacity-60">或："推荐一首适合演唱会气氛的歌"</p>
              </div>
            )}
            <AnimatePresence>
              {orchMessages.map((msg, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div className={`max-w-[75%] px-4 py-2.5 rounded-2xl text-sm ${
                    msg.role === 'user'
                      ? 'bg-neon-blue text-white rounded-br-md'
                      : 'glass border border-white/10 text-gray-200 rounded-bl-md'
                  }`}>
                    {msg.content}
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>

            {/* 思考步骤 */}
            {orchLoading && (
              <div className="space-y-1.5">
                {THINK_STEPS.map((step, i) => (
                  <div key={i} className={`flex items-center space-x-2 text-xs px-3 py-1.5 rounded-lg ${
                    i < currentStep ? 'text-green-400 bg-green-500/5'
                      : i === currentStep ? 'text-neon-blue bg-neon-blue/10 border border-neon-blue/20'
                      : 'text-gray-600'
                  }`}>
                    {i < currentStep
                      ? <Check className="w-3 h-3" />
                      : i === currentStep
                      ? <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}>
                          <Zap className="w-3 h-3" />
                        </motion.div>
                      : <Bot className="w-3 h-3" />
                    }
                    <span>{step}</span>
                  </div>
                ))}
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          {/* 输入区 */}
          <div className="border-t border-white/10 p-3 flex space-x-2">
            <input
              value={chatInput}
              onChange={e => setChatInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleOrchChat()}
              placeholder="告诉 AI 管家你的需求..."
              className="flex-1 px-4 py-2.5 glass rounded-xl border border-white/10 focus:border-neon-blue/50 focus:outline-none text-white text-sm bg-transparent"
            />
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={handleOrchChat}
              disabled={orchLoading || !chatInput.trim()}
              className="px-4 py-2.5 bg-gradient-to-r from-neon-blue to-neon-purple rounded-xl text-white disabled:opacity-40 flex items-center space-x-1.5"
            >
              {orchLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              <span className="text-sm">发送</span>
            </motion.button>
          </div>
        </motion.div>

        {/* 上下文卡片（显示当前会话状态） */}
        {sessionInfo && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6"
          >
            {[
              { label: '歌手', value: sessionInfo.selectedSinger, icon: '🎤' },
              { label: '城市', value: sessionInfo.concertCity, icon: '📍' },
              { label: '预算', value: sessionInfo.budgetLevel, icon: '💰' },
              { label: '心情', value: sessionInfo.mood, icon: '💫' },
            ].filter(f => f.value).map((f, i) => (
              <div key={i} className="glass rounded-xl p-3 border border-white/10 text-center">
                <div className="text-xl mb-1">{f.icon}</div>
                <div className="text-xs text-gray-400">{f.label}</div>
                <div className="text-sm text-white font-medium truncate">{f.value}</div>
              </div>
            ))}
          </motion.div>
        )}

        {/* Tab 导航 */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          {TABS.map(tab => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <motion.button
                key={tab.id}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.97 }}
                onClick={() => setActiveTab(tab.id)}
                className={`relative p-4 rounded-xl border transition-all text-left ${
                  isActive
                    ? 'bg-gradient-to-br ' + tab.color + ' border-transparent'
                    : 'glass border-white/10 hover:border-white/25'
                }`}
              >
                <Icon className={`w-6 h-6 mb-2 ${isActive ? 'text-white' : 'text-white/70'}`} />
                <p className={`font-bold text-sm ${isActive ? 'text-white' : 'text-white/90'}`}>{tab.label}</p>
                <p className={`text-xs mt-0.5 ${isActive ? 'text-white/70' : 'text-white/40'}`}>{tab.desc}</p>
              </motion.button>
            );
          })}
        </div>

        {/* Tab 内容 */}
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -16 }}
            transition={{ duration: 0.25 }}
          >
            <ActiveTabComponent onSelectSinger={onSelectSinger} />
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
};

export default AgentPage;
